IF DB_ID(N'SistemaPedidos') IS NULL CREATE DATABASE SistemaPedidos;
GO
USE SistemaPedidos;
GO
CREATE TABLE Clientes (id_cliente INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Clientes PRIMARY KEY, razon_social VARCHAR(150) NOT NULL, cuit VARCHAR(20) NOT NULL, tipo_cliente VARCHAR(50) NOT NULL, estado_credito VARCHAR(50) NOT NULL);
CREATE TABLE Productos (id_producto INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Productos PRIMARY KEY, descripcion VARCHAR(200) NOT NULL, precio_minorista DECIMAL(18,2) NOT NULL CONSTRAINT CK_Productos_Precio CHECK (precio_minorista >= 0), stock_actual INT NOT NULL CONSTRAINT CK_Productos_Stock CHECK (stock_actual >= 0), stock_minimo INT NOT NULL CONSTRAINT CK_Productos_StockMin CHECK (stock_minimo >= 0));
CREATE TABLE Pedidos (id_pedido INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Pedidos PRIMARY KEY, id_cliente INT NOT NULL, fecha_ingreso DATETIME NOT NULL, estado VARCHAR(50) NOT NULL, CONSTRAINT FK_Pedidos_Clientes FOREIGN KEY (id_cliente) REFERENCES Clientes(id_cliente));
CREATE TABLE Detalles_Items (id_detalle INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Detalles_Items PRIMARY KEY, id_pedido INT NOT NULL, id_producto INT NOT NULL, cantidad INT NOT NULL CONSTRAINT CK_Detalles_Cantidad CHECK (cantidad > 0), precio_unitario DECIMAL(18,2) NOT NULL CONSTRAINT CK_Detalles_Precio CHECK (precio_unitario >= 0), CONSTRAINT FK_Detalles_Pedidos FOREIGN KEY (id_pedido) REFERENCES Pedidos(id_pedido), CONSTRAINT FK_Detalles_Productos FOREIGN KEY (id_producto) REFERENCES Productos(id_producto));
CREATE TABLE Cotizaciones (id_cotizacion INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Cotizaciones PRIMARY KEY, id_pedido INT NOT NULL, fecha_emision DATETIME NOT NULL, monto_total DECIMAL(18,2) NOT NULL, estado VARCHAR(50) NOT NULL, CONSTRAINT FK_Cotizaciones_Pedidos FOREIGN KEY (id_pedido) REFERENCES Pedidos(id_pedido));
CREATE TABLE Ordenes_Compra (id_oc INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Ordenes_Compra PRIMARY KEY, id_cotizacion INT NOT NULL, nro_oc_cliente VARCHAR(50) NOT NULL, fecha_recepcion DATETIME NOT NULL, estado VARCHAR(50) NOT NULL, pago VARCHAR(50) NOT NULL, CONSTRAINT FK_OC_Cotizaciones FOREIGN KEY (id_cotizacion) REFERENCES Cotizaciones(id_cotizacion));
CREATE TABLE Remitos (id_remito INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Remitos PRIMARY KEY, id_oc INT NOT NULL, fecha_emision DATETIME NOT NULL, estado_entrega VARCHAR(50) NOT NULL, firma_digital_cliente VARBINARY(MAX) NULL, CONSTRAINT FK_Remitos_OC FOREIGN KEY (id_oc) REFERENCES Ordenes_Compra(id_oc));
CREATE TABLE Facturas (id_factura INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Facturas PRIMARY KEY, id_remito INT NOT NULL, nro_factura VARCHAR(50) NOT NULL, fecha_emision DATETIME NOT NULL, cae VARCHAR(50) NOT NULL, monto_total DECIMAL(18,2) NOT NULL, CONSTRAINT FK_Facturas_Remitos FOREIGN KEY (id_remito) REFERENCES Remitos(id_remito));
GO
